// State transition logic (combinational)
always@(*)begin
    case(present_state)
        A: if(x) next_state = B;
            else next_state = A;
			 B: if(~x) next_state = C;
				else next_state = A;
			 C: if(x) next_state = C;
				else next_state = D;
			 D: if(x) next_state = E;
				else next_state = A;
			 E: if(x) next_state = B;
				else next_state = D;
    endcase
end

// State flip-flops (sequential)
always@(posedge clk)begin
    present_state <= next_state;
end

